import{_ as t,o as r,c as a,ai as s}from"./chunks/framework.C33Uq6m-.js";const m=JSON.parse('{"title":"Labo de cache","description":"","frontmatter":{},"headers":[],"relativePath":"fr/guide/cache-lab.md","filePath":"fr/guide/cache-lab.md"}'),i={name:"fr/guide/cache-lab.md"};function n(l,e,o,u,d,c){return r(),a("div",null,[...e[0]||(e[0]=[s('<h1 id="labo-de-cache" tabindex="-1">Labo de cache <a class="header-anchor" href="#labo-de-cache" aria-label="Permalink to &quot;Labo de cache&quot;">​</a></h1><p>Le <strong>Labo de cache</strong> vous dit pourquoi votre invite manque le cache du modèle, et mesure ce que cela vous coûte à chaque tour.</p><p><strong>Élément de la barre latérale :</strong> Labo de cache (au-dessus de l&#39;Observatoire des Protocoles) <strong>Route :</strong> <code>/cache-lab</code><strong>Ajouté dans :</strong> v0.6.0 (septembre 2026) <strong>Nécessite :</strong> Ollama 0.33.3 ou plus récent</p><h2 id="quel-est-l-interet" tabindex="-1">Quel est l&#39;intérêt ? <a class="header-anchor" href="#quel-est-l-interet" aria-label="Permalink to &quot;Quel est l&#39;intérêt ?&quot;">​</a></h2><p>Un modèle local ne relit pas toute votre invite à chaque tour. Il conserve un <strong>cache KV</strong> des tokens déjà traités et le réutilise — mais seulement tant que l&#39;invite <strong>correspond encore depuis le tout premier token</strong>.</p><p>Ce « depuis le tout premier token » est toute l&#39;histoire. Le cache survit sur un <em>préfixe</em> partagé. Dès qu&#39;un token diffère, tout ce qui suit est jeté et doit être réévalué, aussi identique soit-il.</p><p>Un seul horodatage en haut d&#39;une invite système vous coûte donc l&#39;invite système entière, à chaque tour. Mesuré sur un démon réel avec la même invite de 324 tokens :</p><table tabindex="0"><thead><tr><th>Position de l&#39;horodatage</th><th>Tokens d&#39;invite</th><th>Réutilisés du cache</th><th>Préremplissage</th></tr></thead><tbody><tr><td>Au <strong>début</strong></td><td>324</td><td>4</td><td>64,6 ms</td></tr><tr><td>À la <strong>fin</strong></td><td>324</td><td>290</td><td>18,6 ms</td></tr></tbody></table><p>Même modèle. Mêmes mots. Même nombre de tokens. <strong>3,5× le temps de préremplissage</strong>, uniquement à cause de la position d&#39;une seule valeur.</p><p>C&#39;est invisible dans tous les autres outils, et c&#39;est l&#39;un des plus grands leviers sur la rapidité ressentie d&#39;un modèle local.</p><h2 id="utiliser-la-page" tabindex="-1">Utiliser la page <a class="header-anchor" href="#utiliser-la-page" aria-label="Permalink to &quot;Utiliser la page&quot;">​</a></h2><ol><li>Choisissez un modèle.</li><li>Collez l&#39;invite système que vous envoyez réellement à chaque tour.</li><li>Cliquez sur <strong>Mesurer</strong>.</li></ol><p>La page fait trois choses.</p><h3 id="diagnostic" tabindex="-1">Diagnostic <a class="header-anchor" href="#diagnostic" aria-label="Permalink to &quot;Diagnostic&quot;">​</a></h3><p>Avant toute mesure, le labo cherche dans votre invite les valeurs qui changent d&#39;un tour à l&#39;autre — horodatages, dates, heures, identifiants de session, longs nombres — et les affiche sous forme d&#39;étiquettes.</p><p>Il rend ensuite votre invite en trois couleurs :</p><ul><li><strong>Vert</strong> — le préfixe que le cache peut garder.</li><li><strong>Rouge</strong> — la première valeur qui change.</li><li><strong>Gris</strong> — tout ce qui est perdu, uniquement parce que placé <em>après</em> cette valeur.</li></ul><p>La zone grise est le point essentiel. C&#39;est généralement la majeure partie de l&#39;invite, et il n&#39;y a généralement rien à lui reprocher.</p><h3 id="mesure" tabindex="-1">Mesure <a class="header-anchor" href="#mesure" aria-label="Permalink to &quot;Mesure&quot;">​</a></h3><p>Le labo envoie <strong>deux dispositions</strong>, chacune <strong>deux fois</strong> :</p><ol><li>Votre invite telle quelle.</li><li>La même invite avec les valeurs changeantes déplacées à la fin.</li></ol><p>Le second envoi de chaque disposition porte une valeur <em>différente</em> — nouvel horodatage, nouvel identifiant — car c&#39;est ce que fait le trafic réel. C&#39;est ce second envoi qui est mesuré. Mesurer le premier ne dirait que la correspondance d&#39;une invite avec elle-même, soit ~100 % pour n&#39;importe quelle disposition, ce qui n&#39;apprend rien.</p><p>Vous obtenez un tableau de ce que le démon a réellement conservé : tokens d&#39;invite, réutilisés, évalués, temps de préremplissage et pourcentage de réutilisation.</p><h3 id="verdict" tabindex="-1">Verdict <a class="header-anchor" href="#verdict" aria-label="Permalink to &quot;Verdict&quot;">​</a></h3><p>Enfin, un énoncé clair de ce qu&#39;a rapporté la réécriture : tokens économisés par tour, millisecondes économisées par tour, et le facteur d&#39;accélération.</p><p>Chaque chiffre de la page provient de votre propre démon. <strong>Rien n&#39;est estimé.</strong></p><h2 id="lire-les-resultats" tabindex="-1">Lire les résultats <a class="header-anchor" href="#lire-les-resultats" aria-label="Permalink to &quot;Lire les résultats&quot;">​</a></h2><p><strong>Réutilisation proche de 100 %</strong> — cette disposition se porte bien. Le cache porte presque toute l&#39;invite.</p><p><strong>Réutilisation proche de 0 % avec une valeur au début</strong> — le cas habituel, et celui qui vaut la peine d&#39;être corrigé. Déplacez les valeurs changeantes à la fin de l&#39;invite système, ou dans le message utilisateur, et le corps au-dessus reste en cache.</p><p><strong>« non rapporté »</strong> — votre démon est antérieur à Ollama 0.33.3 et ne rapporte pas la réutilisation du cache. Le labo n&#39;affichera pas 0 % pour autant, car « le démon n&#39;a rien dit » et « rien n&#39;était en cache » sont deux affirmations différentes, et une seule est un problème.</p><p><strong>Une économie négative</strong> — la réécriture a empiré les choses. Cela arrive ; c&#39;est mesuré, alors croyez-en la mesure plutôt que la théorie.</p><h2 id="que-faire" tabindex="-1">Que faire <a class="header-anchor" href="#que-faire" aria-label="Permalink to &quot;Que faire&quot;">​</a></h2><p>Le remède est presque toujours structurel, et presque toujours gratuit :</p><ul><li>Placez la partie <strong>stable</strong> de votre invite système en premier : rôle, règles, style, exemples.</li><li>Placez ce qui <strong>change à chaque tour</strong> en dernier : l&#39;heure courante, l&#39;identifiant utilisateur, l&#39;identifiant de session, les fragments récupérés.</li><li>Gardez le <strong>contexte récupéré dans un ordre stable</strong>. Réordonner les fragments entre les tours invalide le cache dès le premier fragment déplacé.</li><li>Ne reconstruisez pas l&#39;invite système depuis un gabarit qui resérialise un dictionnaire — l&#39;ordre des clés peut changer à votre insu.</li></ul><p>Rien de tout cela ne modifie ce qui est dit au modèle. Cela ne change que l&#39;endroit où c&#39;est dit, ce qui est gratuit.</p><h2 id="notes-et-limites" tabindex="-1">Notes et limites <a class="header-anchor" href="#notes-et-limites" aria-label="Permalink to &quot;Notes et limites&quot;">​</a></h2><ul><li>Le labo limite la génération à un seul token. Il mesure le <strong>préremplissage</strong> ; le décodage ne serait que du bruit ici.</li><li>La réécriture mesurée est mécanique : elle déplace les segments détectés à la fin et ne touche à rien d&#39;autre. C&#39;est une mesure, pas une invite finale recommandée — relisez-la avant de l&#39;adopter.</li><li>La valeur mutée du « tour suivant » préserve la forme, pas le sens. Une date peut en sortir impossible. C&#39;est sans importance : le cache ne retient que le fait que la valeur a changé, pas ce qu&#39;elle signifie.</li><li>Tout s&#39;exécute sur <code>localhost</code>. Pas de cloud, pas de clé d&#39;API, pas d&#39;inscription.</li></ul>',37)])])}const h=t(i,[["render",n]]);export{m as __pageData,h as default};
